import React, { useState, useEffect } from 'react';
import { 
  DollarSign, 
  TrendingUp, 
  TrendingDown, 
  Target, 
  Calendar, 
  MessageSquare, 
  Award, 
  CreditCard, 
  PiggyBank, 
  AlertCircle,
  Plus,
  Edit3,
  Trash2,
  CheckCircle,
  Home,
  BarChart3,
  Settings
} from 'lucide-react';

// Mock data for development
const mockData = {
  user: {
    name: "Alex Johnson",
    totalBalance: 12580.45,
    monthlyIncome: 5200.00,
    monthlyExpenses: 3840.25,
    healthScore: 78
  },
  transactions: [
    { id: 1, description: "Salary Deposit", amount: 5200.00, type: "income", date: "2024-06-01", category: "Salary" },
    { id: 2, description: "Grocery Store", amount: -120.50, type: "expense", date: "2024-06-02", category: "Food" },
    { id: 3, description: "Gas Station", amount: -65.00, type: "expense", date: "2024-06-03", category: "Transportation" },
    { id: 4, description: "Freelance Work", amount: 800.00, type: "income", date: "2024-06-04", category: "Freelance" },
    { id: 5, description: "Restaurant", amount: -85.30, type: "expense", date: "2024-06-05", category: "Food" }
  ],
  budgets: [
    { id: 1, category: "Food", allocated: 600, spent: 340.80, color: "#FF6B6B" },
    { id: 2, category: "Transportation", allocated: 300, spent: 180.50, color: "#4ECDC4" },
    { id: 3, category: "Entertainment", allocated: 200, spent: 125.00, color: "#45B7D1" },
    { id: 4, category: "Shopping", allocated: 400, spent: 280.30, color: "#96CEB4" }
  ],
  goals: [
    { id: 1, title: "Emergency Fund", target: 10000, current: 6500, deadline: "2024-12-31" },
    { id: 2, title: "Vacation Fund", target: 3000, current: 1200, deadline: "2024-08-15" },
    { id: 3, title: "New Car", target: 25000, current: 8500, deadline: "2025-06-01" }
  ]
};

// Layout Component
const Layout = ({ children, activeTab, setActiveTab }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: Home },
    { id: 'budget', label: 'Budget', icon: BarChart3 },
    { id: 'goals', label: 'Goals', icon: Target },
    { id: 'transactions', label: 'Transactions', icon: CreditCard },
    { id: 'ai', label: 'AI Assistant', icon: MessageSquare }
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      {/* Sidebar */}
      <nav style={{
        width: '250px',
        backgroundColor: '#1e293b',
        padding: '20px',
        boxShadow: '2px 0 10px rgba(0,0,0,0.1)'
      }}>
        <div style={{ marginBottom: '40px' }}>
          <h1 style={{ 
            color: '#white', 
            fontSize: '24px', 
            fontWeight: 'bold',
            margin: 0,
            color: '#fff'
          }}>
            💸 FinanceApp
          </h1>
        </div>

        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {navItems.map(item => {
            const Icon = item.icon;
            return (
              <li key={item.id} style={{ marginBottom: '8px' }}>
                <button
                  onClick={() => setActiveTab(item.id)}
                  style={{
                    width: '100%',
                    padding: '12px 16px',
                    backgroundColor: activeTab === item.id ? '#3b82f6' : 'transparent',
                    color: activeTab === item.id ? '#fff' : '#cbd5e1',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '12px',
                    fontSize: '14px',
                    fontWeight: '500',
                    transition: 'all 0.2s'
                  }}
                >
                  <Icon size={18} />
                  {item.label}
                </button>
              </li>
            );
          })}
        </ul>
      </nav>

      {/* Main Content */}
      <main style={{ flex: 1, padding: '20px', overflow: 'auto' }}>
        {children}
      </main>
    </div>
  );
};

// Dashboard Component
const Dashboard = ({ data }) => {
  const netIncome = data.user.monthlyIncome - data.user.monthlyExpenses;
  const savingsRate = ((netIncome / data.user.monthlyIncome) * 100).toFixed(1);

  return (
    <div>
      <div style={{ marginBottom: '30px' }}>
        <h2 style={{ fontSize: '32px', fontWeight: 'bold', margin: 0, color: '#1e293b' }}>
          Welcome back, {data.user.name}!
        </h2>
        <p style={{ color: '#64748b', margin: '8px 0 0 0' }}>
          Here's your financial overview for this month
        </p>
      </div>

      {/* Key Metrics */}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', 
        gap: '20px',
        marginBottom: '30px'
      }}>
        <MetricCard
          title="Total Balance"
          value={`$${data.user.totalBalance.toLocaleString()}`}
          icon={DollarSign}
          color="#22c55e"
        />
        <MetricCard
          title="Monthly Income"
          value={`$${data.user.monthlyIncome.toLocaleString()}`}
          icon={TrendingUp}
          color="#3b82f6"
        />
        <MetricCard
          title="Monthly Expenses"
          value={`$${data.user.monthlyExpenses.toLocaleString()}`}
          icon={TrendingDown}
          color="#ef4444"
        />
        <MetricCard
          title="Savings Rate"
          value={`${savingsRate}%`}
          icon={PiggyBank}
          color="#8b5cf6"
        />
      </div>

      {/* Charts and Recent Activity */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
        <Card title="Recent Transactions">
          <TransactionsList transactions={data.transactions.slice(0, 5)} />
        </Card>

        <Card title="Financial Health">
          <div style={{ textAlign: 'center', padding: '20px' }}>
            <div style={{
              width: '120px',
              height: '120px',
              borderRadius: '50%',
              background: `conic-gradient(#22c55e 0deg ${data.user.healthScore * 3.6}deg, #e5e7eb ${data.user.healthScore * 3.6}deg 360deg)`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              margin: '0 auto 20px'
            }}>
              <div style={{
                width: '90px',
                height: '90px',
                borderRadius: '50%',
                backgroundColor: '#fff',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '24px',
                fontWeight: 'bold',
                color: '#1e293b'
              }}>
                {data.user.healthScore}
              </div>
            </div>
            <p style={{ color: '#64748b', margin: 0 }}>
              Your financial health score is looking good!
            </p>
          </div>
        </Card>
      </div>
    </div>
  );
};

// Budget Component
const Budget = ({ data }) => {
  return (
    <div>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginBottom: '30px'
      }}>
        <h2 style={{ fontSize: '32px', fontWeight: 'bold', margin: 0, color: '#1e293b' }}>
          Budget Overview
        </h2>
        <button style={{
          padding: '12px 24px',
          backgroundColor: '#3b82f6',
          color: 'white',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          fontSize: '14px',
          fontWeight: '500'
        }}>
          <Plus size={16} />
          Add Budget
        </button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
        {data.budgets.map(budget => (
          <BudgetCard key={budget.id} budget={budget} />
        ))}
      </div>
    </div>
  );
};

// Goals Component
const Goals = ({ data }) => {
  return (
    <div>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginBottom: '30px'
      }}>
        <h2 style={{ fontSize: '32px', fontWeight: 'bold', margin: 0, color: '#1e293b' }}>
          Financial Goals
        </h2>
        <button style={{
          padding: '12px 24px',
          backgroundColor: '#3b82f6',
          color: 'white',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          fontSize: '14px',
          fontWeight: '500'
        }}>
          <Plus size={16} />
          New Goal
        </button>
      </div>

      <div style={{ display: 'grid', gap: '20px' }}>
        {data.goals.map(goal => (
          <GoalCard key={goal.id} goal={goal} />
        ))}
      </div>
    </div>
  );
};

// Transactions Component
